import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // General rule: for any inputs, after initialize(...) completes successfully, c.nft() equals the _nft parameter passed.
    // Fuzzed parameters: _baseToken and _nft addresses and numeric parameters; the fuzzer will search for inputs that expose the mutant.
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // keep wide admissible domain but avoid trivial disallowed feeRate > limit to allow initialize to revert in both versions
        // we allow any addresses (including zero) because initialize accepts address(0) for baseToken
        // constrain feeRate to <= 5000 so initialize should not revert due to FeeRateTooHigh in the reference
        if (_feeRate > 5000) return;

        // call initialize and capture whether it succeeded
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // If initialize reverted, the rule is vacuously satisfied for this input (we only assert when it succeeded)
        if (!ok) return;

        // Exactly one assertion: after successful initialize, nft() must equal the _nft argument passed.
        assertTrue(c.nft() == _nft);
    }
}

