pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // General property: after initialize(...) completes successfully, c.nft() equals the supplied _nft argument.
    // The mutant that assigns nft = address(0) will violate this for any _nft != address(0).
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // Keep domains wide but avoid impossible feeRate that the contract rejects always
        vm.assume(_feeRate <= 5000);

        // Call initialize as an arbitrary caller
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            // If initialize reverts (e.g. re-initialization), we cannot assert nft equality; require it succeeded
            ok = false;
        }

        // Only assert the property when initialize succeeded. The reference always stores the supplied _nft;
        // the mutant that sets nft = address(0) will fail for some inputs where _nft != address(0).
        if (ok) {
            assertTrue(c.nft() == _nft);
        }
    }
}

