pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 _changeFee, address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // Keep feeRate within allowed bounds broadly
        if (_feeRate > 60000) _feeRate = uint16(_feeRate % 60001);
        // ensure we don't pass an already-initialized contract
        // call initialize and observe stored changeFee equals the supplied parameter
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            // If initialize reverts (e.g. due to FeeRateTooHigh), we treat as not-ok for this call
            ok = false;
        }

        // If initialize reverted we cannot read changeFee meaningfully for that call; restrict assertion to successful initializations
        if (ok) {
            // The universal property: stored changeFee equals the supplied _changeFee
            assertTrue(c.changeFee() == _changeFee);
        } else {
            // If initialize failed due to fee rate > 5000 the reference and mutant both revert; nothing to assert
            // We still need a single assertTrue per test execution path, so assert that feeRate is invalid (causes revert)
            assertTrue(_feeRate > 5000);
        }
    }
}
